import{_ as a,c as o,o as r,j as d,Y as s,t as n}from"./chunks/framework.BNTND4LZ.js";const u=JSON.parse('{"title":"od | x-cmd man (man1) | dump files in octal and other formats","titleTemplate":false,"description":"x-cmd man (man1 Manual Page) | od - dump files in octal and other formats","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"od | x-cmd man (man1) | dump files in octal and other formats"}],["meta",{"name":"og:description","content":"x-cmd man (man1 Manual Page) | od - dump files in octal and other formats"}]]},"headers":[],"params":{"isMan":true,"man":"od","category":"man1","desc":"dump files in octal and other formats"},"relativePath":"man1/od.md","filePath":"man1/[man].md"}'),i={name:"man1/od.md"},l={class:"visually-hidden"};function m(e,t,g,c,p,h){return r(),o("div",null,[d("h1",l,n(e.$params.man),1),t[0]||(t[0]=s('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>od - dump files in octal and other formats</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p><strong>od</strong> [<em>OPTION</em>]... [<em>FILE</em>]... <br> <strong>od</strong> [<em>-abcdfilosx</em>]... [<em>FILE</em>] [[<em>+</em>]<em>OFFSET</em>[<em>.</em>][<em>b</em>]] <br> <strong>od</strong> <em>--traditional <em>[<em>OPTION</em>]... [<em>FILE</em>] [[</em>+</em>]<em>OFFSET</em>[<em>.</em>][<em>b</em>] [<em>+</em>][<em>LABEL</em>][<em>.</em>][<em>b</em>]]</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Write an unambiguous representation, octal bytes by default, of FILE to standard output. With more than one FILE argument, concatenate them in the listed order to form the input.</p><p>With no FILE, or when FILE is -, read standard input.</p><p>If first and second call formats both apply, the second format is assumed if the last operand begins with + or (if there are 2 operands) a digit. An OFFSET operand means <strong>-j</strong> OFFSET. LABEL is the pseudo-address at first byte printed, incremented when dump is progressing. For OFFSET and LABEL, a 0x or 0X prefix indicates hexadecimal; suffixes may be . for octal and b for multiply by 512.</p><p>Mandatory arguments to long options are mandatory for short options too.</p><dl><dt><strong>-A</strong>, <strong>--address-radix</strong>=<em>RADIX</em></dt><dd>output format for file offsets; RADIX is one of [doxn], for Decimal, Octal, Hex or None</dd><dt><strong>--endian=</strong>{big|little}</dt><dd>swap input bytes according the specified order</dd><dt><strong>-j</strong>, <strong>--skip-bytes</strong>=<em>BYTES</em></dt><dd>skip BYTES input bytes first</dd><dt><strong>-N</strong>, <strong>--read-bytes</strong>=<em>BYTES</em></dt><dd>limit dump to BYTES input bytes</dd><dt><strong>-S</strong> BYTES, <strong>--strings</strong>[=<em>BYTES</em>]</dt><dd>show only NUL terminated strings of at least BYTES (3) printable characters</dd><dt><strong>-t</strong>, <strong>--format</strong>=<em>TYPE</em></dt><dd>select output format or formats</dd><dt><strong>-v</strong>, <strong>--output-duplicates</strong></dt><dd>do not use * to mark line suppression</dd><dt><strong>-w[BYTES]</strong>, <strong>--width</strong>[=<em>BYTES</em>]</dt><dd>output BYTES bytes per output line; 32 is implied when BYTES is not specified</dd><dt><strong>--traditional</strong></dt><dd>accept arguments in third form above</dd><dt><strong>--help</strong></dt><dd>display this help and exit</dd><dt><strong>--version</strong></dt><dd>output version information and exit</dd></dl><h3 id="traditional-format-specifications-may-be-intermixed-they-accumulate" tabindex="-1">Traditional format specifications may be intermixed; they accumulate: <a class="header-anchor" href="#traditional-format-specifications-may-be-intermixed-they-accumulate" aria-label="Permalink to &quot;Traditional format specifications may be intermixed; they accumulate:&quot;">​</a></h3><dl><dt><strong>-a</strong></dt><dd>same as <strong>-t</strong> a, select named characters, ignoring high-order bit</dd><dt><strong>-b</strong></dt><dd>same as <strong>-t</strong> o1, select octal bytes</dd><dt><strong>-c</strong></dt><dd>same as <strong>-t</strong> c, select printable characters or backslash escapes</dd><dt><strong>-d</strong></dt><dd>same as <strong>-t</strong> u2, select unsigned decimal 2-byte units</dd><dt><strong>-f</strong></dt><dd>same as <strong>-t</strong> fF, select floats</dd><dt><strong>-i</strong></dt><dd>same as <strong>-t</strong> dI, select decimal ints</dd><dt><strong>-l</strong></dt><dd>same as <strong>-t</strong> dL, select decimal longs</dd><dt><strong>-o</strong></dt><dd>same as <strong>-t</strong> o2, select octal 2-byte units</dd><dt><strong>-s</strong></dt><dd>same as <strong>-t</strong> d2, select decimal 2-byte units</dd><dt><strong>-x</strong></dt><dd>same as <strong>-t</strong> x2, select hexadecimal 2-byte units</dd></dl><h3 id="type-is-made-up-of-one-or-more-of-these-specifications" tabindex="-1">TYPE is made up of one or more of these specifications: <a class="header-anchor" href="#type-is-made-up-of-one-or-more-of-these-specifications" aria-label="Permalink to &quot;TYPE is made up of one or more of these specifications:&quot;">​</a></h3><dl><dt>a</dt><dd>named character, ignoring high-order bit</dd><dt>c</dt><dd>printable character or backslash escape</dd><dt>d[SIZE]</dt><dd>signed decimal, SIZE bytes per integer</dd><dt>f[SIZE]</dt><dd>floating point, SIZE bytes per float</dd><dt>o[SIZE]</dt><dd>octal, SIZE bytes per integer</dd><dt>u[SIZE]</dt><dd>unsigned decimal, SIZE bytes per integer</dd><dt>x[SIZE]</dt><dd>hexadecimal, SIZE bytes per integer</dd></dl><p>SIZE is a number. For TYPE in [doux], SIZE may also be C for sizeof(char), S for sizeof(short), I for sizeof(int) or L for sizeof(long). If TYPE is f, SIZE may also be F for sizeof(float), D for sizeof(double) or L for sizeof(long double).</p><p>Adding a z suffix to any type displays printable characters at the end of each output line.</p><h3 id="bytes-is-hex-with-0x-or-0x-prefix-and-may-have-a-multiplier-suffix" tabindex="-1">BYTES is hex with 0x or 0X prefix, and may have a multiplier suffix: <a class="header-anchor" href="#bytes-is-hex-with-0x-or-0x-prefix-and-may-have-a-multiplier-suffix" aria-label="Permalink to &quot;BYTES is hex with 0x or 0X prefix, and may have a multiplier suffix:&quot;">​</a></h3><dl><dt>b</dt><dd>512</dd><dt>KB</dt><dd>1000</dd><dt>K</dt><dd>1024</dd><dt>MB</dt><dd>1000*1000</dd><dt>M</dt><dd>1024*1024</dd></dl><p>and so on for G, T, P, E, Z, Y, R, Q. Binary prefixes can be used, too: KiB=K, MiB=M, and so on.</p><h2 id="examples" tabindex="-1">EXAMPLES <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;EXAMPLES&quot;">​</a></h2><dl><dt><strong>od -A x -t x1z -v</strong></dt><dd>Display hexdump format output</dd><dt><strong>od -A o -t oS -w16</strong></dt><dd>The default output format used by od</dd></dl><h2 id="author" tabindex="-1">AUTHOR <a class="header-anchor" href="#author" aria-label="Permalink to &quot;AUTHOR&quot;">​</a></h2><p>Written by Jim Meyering.</p><h2 id="reporting-bugs" tabindex="-1">REPORTING BUGS <a class="header-anchor" href="#reporting-bugs" aria-label="Permalink to &quot;REPORTING BUGS&quot;">​</a></h2><p>GNU coreutils online help: &lt;<a href="https://www.gnu.org/software/coreutils/%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/\\</a>&gt; <br> Report any translation bugs to &lt;<a href="https://translationproject.org/team/%5C" target="_blank" rel="noreferrer">https://translationproject.org/team/\\</a>&gt;</p><h2 id="copyright" tabindex="-1">COPYRIGHT <a class="header-anchor" href="#copyright" aria-label="Permalink to &quot;COPYRIGHT&quot;">​</a></h2><p>Copyright © 2023 Free Software Foundation, Inc. License GPLv3+: GNU GPL version 3 or later &lt;<a href="https://gnu.org/licenses/gpl.html%5C" target="_blank" rel="noreferrer">https://gnu.org/licenses/gpl.html\\</a>&gt;. <br> This is free software: you are free to change and redistribute it. There is NO WARRANTY, to the extent permitted by law.</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p>Full documentation &lt;<a href="https://www.gnu.org/software/coreutils/od%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/od\\</a>&gt; <br> or available locally via: info &#39;(coreutils) od invocation&#39;</p>',29))])}const b=a(i,[["render",m]]);export{u as __pageData,b as default};
